export type TicketStatus="OPEN"|"IN_PROGRESS"|"CLOSED";export type Priority="LOW"|"NORMAL"|"HIGH";export type Ticket={id:number;title:string;description:string;status:TicketStatus;priority:Priority;assignee:string|null;createdAt:string;tags:readonly string[]};export type Page<T>={items:readonly T[];total:number;page:number;pageSize:number};export type CreateTicketBody=Pick<Ticket,"title"|"description"|"priority"|"assignee">;export type UpdateTicketBody=Partial<Pick<Ticket,"title"|"status"|"priority"|"assignee">>;export type ApiError={message:string;fieldErrors?:Partial<Record<keyof CreateTicketBody,readonly string[]>>};export type TicketListQuery={status?:TicketStatus;q?:string;page?:number;pageSize?:number;sort?:`${"createdAt"|"priority"|"title"}:${"asc"|"desc"}`};export function ticketUrl(id:number):string{if(!Number.isSafeInteger(id)||id<0)throw RangeError("ID musi być nieujemną bezpieczną liczbą całkowitą");return "/api/tickets/"+id;}export function ticketsUrl(query:TicketListQuery={}):string{const params=new URLSearchParams();if(query.status!==undefined){if(!["OPEN","IN_PROGRESS","CLOSED"].includes(query.status))throw Error("Status");params.set("status",query.status);}const q=query.q?.trim();if(q)params.set("q",q);if(query.page!==undefined){if(!Number.isSafeInteger(query.page)||query.page<1)throw RangeError("Page");params.set("page",String(query.page));}if(query.pageSize!==undefined){if(!Number.isSafeInteger(query.pageSize)||query.pageSize<1||query.pageSize>100)throw RangeError("PageSize");params.set("pageSize",String(query.pageSize));}if(query.sort!==undefined){if(!/^(createdAt|priority|title):(asc|desc)$/.test(query.sort))throw Error("Sort");params.set("sort",query.sort);}const search=params.toString();return "/api/tickets"+(search?"?"+search:"");}export function statusAction(status:number):string{if(status===204)return "no-content";if(status>=200&&status<300)return "success";if(status===400||status===422)return "validation";if(status===401)return "authenticate";if(status===403)return "forbidden";if(status===404)return "not-found";if(status===409)return "conflict";if(status===429)return "rate-limit";if(status>=500&&status<=599)return "server-error";return "unexpected";}
export function optimisticPriority(ticket:Ticket|undefined,priority:Priority):Ticket|undefined{return ticket===undefined?undefined:ticket.priority===priority?ticket:{...ticket,priority};}export function rollbackAllowed(current:Ticket|undefined,optimistic:Ticket|undefined):boolean{return optimistic!==undefined&&current===optimistic;}
export type TicketAction={kind:"priority";priority:Priority}|{kind:"close"}|{kind:"delete"};const locks=new WeakMap<QueryClient,Map<number,object>>();function acquire(client:QueryClient,id:number){let map=locks.get(client);if(!map){map=new Map();locks.set(client,map);}if(map.has(id))throw Error("Inna operacja tego ticketu jeszcze trwa.");const token={};map.set(id,token);return token;}function release(client:QueryClient,id:number,token:object){const map=locks.get(client);if(map?.get(id)===token)map.delete(id);}export const ticketWriteKey=(id:number)=>["tickets","write",id] as const;export function ticketMutationOptions(client:QueryClient,id:number){const key=ticketKeys.detail(id);return {mutationKey:ticketWriteKey(id),retry:false as const,mutationFn:async(action:TicketAction):Promise<Ticket|null>=>{if(action.kind==="delete"){await deleteTicket(id);return null;}return updateTicket(id,action.kind==="close"?{status:"CLOSED"}:{priority:action.priority});},onMutate:async(action:TicketAction)=>{const token=acquire(client,id);try{await client.cancelQueries({queryKey:key,exact:true});const previous=client.getQueryData<Ticket>(key);let optimistic:Ticket|undefined;if(action.kind==="priority"&&previous){client.setQueryData<Ticket>(key,optimisticPriority(previous,action.priority));optimistic=client.getQueryData<Ticket>(key);}return {token,previous,optimistic};}catch(error){release(client,id,token);throw error;}},onError:(_error:unknown,_action:TicketAction,context:{token:object;previous:Ticket|undefined;optimistic:Ticket|undefined}|undefined)=>{if(context&&rollbackAllowed(client.getQueryData<Ticket>(key),context.optimistic))client.setQueryData<Ticket>(key,context.previous);},onSuccess:(updated:Ticket|null)=>{if(updated)client.setQueryData<Ticket>(key,updated);else client.removeQueries({queryKey:key,exact:true});},onSettled:async(_updated:Ticket|null|undefined,_error:unknown,action:TicketAction,context:{token:object}|undefined)=>{if(!context)return;try{await Promise.all([client.invalidateQueries({queryKey:ticketKeys.lists()}),...(action.kind==="delete"?[]:[client.invalidateQueries({queryKey:key,exact:true})])]).catch(()=>undefined);}finally{release(client,id,context.token);}}};}export function useTicketMutation(id:number){const client=useQueryClient();const mutation=useMutation(ticketMutationOptions(client,id));const busy=useIsMutating({mutationKey:ticketWriteKey(id),exact:true})>0;return {mutation,busy};}export function useCreateTicket(){const client=useQueryClient();return useMutation({mutationKey:["tickets","create"] as const,retry:false,mutationFn:(body:CreateTicketBody)=>createTicket(body),onSuccess:async ticket=>{client.setQueryData(ticketKeys.detail(ticket.id),ticket);await client.invalidateQueries({queryKey:ticketKeys.lists()}).catch(()=>undefined);}});}

